function render(){drawGround();drawWorldObjects();drawOverlay();for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx;p.y+=p.vy;p.life-=.016;if(p.life<=0)particles.splice(i,1);else{ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();ctx.globalAlpha=1}}}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function totalItems(){return Object.values(inventory).reduce((a,b)=>a+b,0)}function itemCount(id){return inventory[id]||0}
function give(id,n=1){inventory[id]=(inventory[id]||0)+n;updateHUD()}
function take(id,n=1){if(mode==='builder')return true;if(itemCount(id)<n)return false;inventory[id]-=n;if(inventory[id]<=0)delete inventory[id];return true}
function updateHUD(){const values={hp:player.hp,food:player.food,water:player.water,warm:player.warm,stam:player.stamina,mind:player.mind};for(let k in values){let v=Math.round(clamp(values[k],0,100));$(k+'Bar').style.width=v+'%';$(k+'Val').textContent=v;$(k+'Bar').className='fill'+(v<25?' danger':v<48?' warn':'')}let sec=gameTime%60,day=Math.floor(gameTime/60)+1;player.days=day;let night=sec>=40;let season=mode==='winter'?1:(Math.floor((day-1)/7)%4);$('dayLabel').textContent=`${night?'Ночь':'День'} ${day} · ${seasonNames[season]}`;$('weather').textContent=weatherList[weatherIndex];let z=zoneAt(Math.floor(player.x),Math.floor(player.y));$('locationName').textContent=z.name;$('coords').textContent=`СЕКТОР ${String(Math.floor(player.x)+1).padStart(2,'0')} · ${String(Math.floor(player.y)+1).padStart(2,'0')}`;$('tempLabel').textContent=(Math.round(player.warm/4-15))+'°';$('ailments').textContent=`${player.dirt>60?'🧼 Грязь опасна':'🧼 Чистый'} · ${player.bleed?'🩸 Кровотечение':player.broken?'🦴 Перелом':player.poison?'☠️ Отравление':'🩹 Без ран'}`;updateGoal();}
function updateGoal(){let title='Разведать округу',text='Осмотрись вокруг и собери первые припасы у лесной опушки.',prog=8;if(goal===0){title='Разведать округу';text='Собери 4 ресурса и устрой первый привал.';prog=clamp(totalItems()*9,8,66);if(totalItems()>=4)goal=1}else if(goal===1){title='Тёплый привал';text=campBuilt?'Разожги костёр перед наступлением ночи.':'Собери ветки и волокно, затем построй укрытие.';prog=campBuilt?70:40;if(campBuilt&&fire)goal=2}else if(goal===2){title='Найти детали рации';text=`Обыщи старый городок или станцию. Деталей: ${radioParts}/3.`;prog=70+radioParts*8;if(radioParts>=3)goal=3}else{title='Сигнал с горы';text=hasRadio?'Поднимись на хребет Ворона и вызови помощь.':'Собери ещё детали и изготовь рацию на горной вершине.';prog=hasRadio?95:88}$('goalTitle').textContent=title;$('goalText').textContent=text;$('goalProgress').style.width=prog+'%';}
function addDebris(x,y,color){for(let i=0;i<5;i++)debris.push({x:x+(Math.random()-.5)*.4,y:y+(Math.random()-.5)*.4,z:5+Math.random()*18,vx:(Math.random()-.5)*.025,vy:(Math.random()-.5)*.02,size:.06+Math.random()*.09,color,life:2})}
function nearNode(){let best=null,dist=2.1;for(let n of resourceNodes){if(!n.alive)continue;let d=Math.hypot(n.x-player.x,n.y-player.y);if(d<dist){best=n;dist=d}}return best}
function regionInteract(z){if(z.kind==='town'){if(Math.random()<.58){give('scrap');radioParts++;toast('🔩 Найдены детали старой рации')}else{give('wood',2);toast('🏚️ Разобрал гнилой ящик: +2 ветки')}return true}if(z.kind==='rad'){player.radiation=clamp(player.radiation+5,0,100);player.mind=Math.max(0,player.mind-2);if(Math.random()<.4){give('scrap');radioParts++;toast('☢️ Радиация растёт · найден модуль рации')}else{give('crystal');toast('🔮 В пыли мерцает странный осколок')}return true}if(z.kind==='cave'){if(player.y<5&&player.x<5){if(itemCount('crystal')>=1&&!artifactActive){artifactActive=true;take('crystal');endingNow('dark');return true}if(!artifactActive){give('crystal');toast('🕳️ В глубине найден осколок артефакта');return true}}}if(z.kind==='mountain'){if(radioParts>=3&&!hasRadio){hasRadio=true;give('radio');toast('📻 Рация собрана! Сигнал у вершины вызовет спасателей.')}else if(hasRadio){endingNow('rescue')}else toast(`⛰️ Для ремонта нужны детали: ${radioParts}/3`);return true}if(z.kind==='lake'){give('water');player.water=clamp(player.water+18,0,100);toast('🌊 Набрал чистой воды у карьера');return true}if(z.kind==='farm'){if(Math.random()<.5){give('meat');toast('🌾 В старом амбаре нашлось мясо')}else{give('fiber',2);toast('🌾 Собрано волокно: +2')}return true}return false}
function act(){if(!running||paused)return;if(buildMode){buildStructure();return}let n=nearNode();if(n){if(n.type==='beast'){let i=n.beast;if(n.tamed){toast('🐾 Зверь уже доверяет тебе');return}if(itemCount('berries')+itemCount('meat')<=0){toast('Нужна еда, чтобы приручить зверя');return}if(!take(itemCount('berries')?'berries':'meat'))return;n.tamed=true;animalsFound++;give('hide');if(animalsFound>=8&&amulets>=4)endingNow('ascent');toast(`${animals[i]} приручён · верных зверей ${animalsFound}/8`);return}n.alive=false;n.regrow=120;let amount=n.type==='wood'?2:1;give(n.type,amount);if(n.type==='scrap')radioParts++;if(n.type==='berries'){player.food=clamp(player.food+7,0,100)}if(n.type==='mushroom'){if(Math.random()<.14){player.poison=20;toast('☠️ Похоже, гриб оказался ядовитым')}else player.food=clamp(player.food+9,0,100)}if(n.type==='fish'||n.type==='meat')player.food=clamp(player.food+5,0,100);let icon=itemData[n.type]?.icon||'✦';toast(`${icon} ${itemData[n.type]?.name||'Добыча'} · +${amount}`);addDebris(n.x,n.y,'#cab989');return}if(regionInteract(zoneAt(Math.floor(player.x),Math.floor(player.y))))return;if(player.x>2&&player.x<4&&player.y>2&&player.y<4){if(!campBuilt){buildCamp();return}if(!fire){lightFire();return}player.warm=clamp(player.warm+20,0,100);player.mind=clamp(player.mind+5,0,100);toast('🔥 Согрелся у костра');return}if(enemy){attackEnemy();return}toast('Здесь пока нечего сделать. Исследуй округу.');}
function buildCamp(){if(mode!=='builder'&&(!take('wood',4)||!take('fiber',2))){toast('Нужно: 🪵 4 ветки и 🌾 2 волокна');return}campBuilt=true;give('wall');toast('🛖 Укрытие поставлено у лесной опушки');addDebris(2.5,2.5,'#96734b');}
function lightFire(){if(mode!=='builder'&&!take('wood',2)){toast('Нужно 2 ветки, чтобы разжечь костёр');return}fire={fuel:90};player.warm=clamp(player.warm+22,0,100);toast('🔥 Костёр горит. Ночь уже не так страшна.');}
function buildStructure(){if(mode!=='builder'&&(!take('wood',6)||!take('fiber',2))){toast('Стена: 🪵 6 веток + 🌾 2 волокна');return}give('wall');addDebris(player.x+.5,player.y+.4,'#a8875e');toast('🪵 Стена установлена. Нагрузка: 0 / 180 кг');}
function attackEnemy(){if(!enemy)return;let damage=selectedTool==='spear'?30:selectedTool==='axe'?18:5;enemy.hp-=damage;player.stamina=Math.max(0,player.stamina-8);toast(`⚔️ Удар · ${damage} урона`);addDebris(enemy.x,enemy.y,'#a65040');if(enemy.hp<=0){give('meat');if(Math.random()<.4)give('hide');enemy=null;player.mind=clamp(player.mind+4,0,100);toast('🐺 Угроза устранена · добыча собрана');}}
function craft(id){let r=recipes.find(x=>x.id===id);if(!r)return;for(let [k,v] of Object.entries(r.need))if(mode!=='builder'&&itemCount(k)<v){toast('Не хватает материалов для рецепта');return}for(let [k,v] of Object.entries(r.need))take(k,v);give(id);toast(`${r.icon} Изготовлено: ${r.name} · ${r.time} сек.`);updateModal()}
function useItem(id){if(!take(id))return;if(id==='water'){player.water=clamp(player.water+48,0,100)}else if(id==='berries'||id==='mushroom'||id==='meat'||id==='fish'){player.food=clamp(player.food+(id==='meat'?34:id==='fish'?30:18),0,100);if(id==='meat'&&Math.random()<.15)player.poison=30}else if(id==='bandage'){player.bleed=0;player.hp=clamp(player.hp+22,0,100);player.broken=false}else if(id==='herb'){player.poison=0;player.hp=clamp(player.hp+8,0,100)}else if(id==='torch'){selectedTool='torch';toast('🔥 Факел зажжён')}else if(id==='spear'){selectedTool='spear';toast('🔱 Копьё готово')}else if(id==='charm'){amulets++;if(amulets>=4&&animalsFound>=8)endingNow('ascent')}else{give(id);toast('Предмет экипирован')}updateHUD();updateModal()}
function openModal(type){paused=true;$('modal').classList.add('open');$('modalEyebrow').textContent=type==='bag'?'Снаряжение':type==='craft'?'Полевые рецепты':'Карта округа';$('modalTitle').textContent=type==='bag'?'Рюкзак':type==='craft'?'Ремесло':'Таёжный округ';let body=$('modalBody');if(type==='bag'){let html=`<p>Груз: ${Object.entries(inventory).reduce((a,[id,n])=>a+(itemData[id]?.mass||.5)*n,0).toFixed(1)} кг · ${totalItems()} предметов</p><div class="grid">`;for(let [id,count] of Object.entries(inventory)){let d=itemData[id]||{icon:'📦',name:id,mass:.5};html+=`<button class="slot" data-use="${id}"><span class="item-emoji">${d.icon}</span><b>${d.name} ×${count}</b><small>${(d.mass*count).toFixed(1)} кг · нажми, чтобы использовать</small></button>`}if(!totalItems())html+='<p>Рюкзак пуст. Исследуй лес и собирай припасы.</p>';html+='</div>';body.innerHTML=html;body.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useItem(b.dataset.use))}else if(type==='craft'){let html='<p>Короткие рецепты для долгой зимы. На изготовление уходит игровое время.</p>';for(let r of recipes){let needs=Object.entries(r.need).map(([k,v])=>`${itemData[k].icon} ${v}`).join(' · ');let ok=mode==='builder'||Object.entries(r.need).every(([k,v])=>itemCount(k)>=v);html+=`<div class="recipe"><div><h4>${r.icon} ${r.name} <small>· ${r.time} сек.</small></h4><small>${r.desc}<br>${needs}</small></div><button data-craft="${r.id}" ${ok?'':'disabled'}>Сделать</button></div>`}html+='<div class="recipe"><div><h4>📿 Кольцо тайги</h4><small>Собери 4 амулета в пещерах и приручи 8 зверей.</small></div><span>'+amulets+'/4</span></div>';body.innerHTML=html;body.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft))}else{let html='<p>Округ — 5 × 5 км. Двигайся между секторами, ориентируясь по значкам. Мир и ресурсы постепенно меняются.</p><div class="map-grid">';for(let y=0;y<5;y++)for(let x=0;x<5;x++){let z=zoneAt(x,y),cur=Math.floor(player.x)===x&&Math.floor(player.y)===y;html+=`<div class="map-cell ${cur?'current':''}" data-go="${x},${y}">${z.emoji}<small>${z.name.split(' ')[0]}</small></div>`}html+='</div><div class="map-legend"><span>📍 Ты здесь</span><span>🔩 Детали — город / станция</span><span>⛰️ Рация — вершина</span><span>🕳️ Артефакт — пещера</span></div>';body.innerHTML=html;body.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{let [x,y]=b.dataset.go.split(',').map(Number);player.x=x+.5;player.y=y+.5;visited.add(x+','+y);closeModal();updateHUD();toast(`📍 Путь проложен: ${zoneAt(x,y).name}`)})}}
function closeModal(){ $('modal').classList.remove('open');paused=false;}

