function closeModal(){ $('modal').classList.remove('open');paused=false;}
let caveFinds=0;
function endingNow(kind){if($('ending').classList.contains('open'))return;paused=true;let data=kind==='survive'?['🏕️','Ты выстоял','Тридцать дней тайга испытывала тебя на прочность. Ты построил лагерь, нашёл своё место и пережил долгую зиму. История не закончилась — она стала твоей.']:kind==='rescue'?['📻','Сигнал услышан','Рация ожила на вершине хребта. Через несколько минут в сером небе появился огонёк спасательного борта. Ты больше не один.']:kind==='dark'?['🔮','Тёмный путь','Артефакт отозвался на прикосновение. Лес замер, а из-под земли ответил низкий гул. Тайга открыла тебе дверь, которую не стоило искать.']:['📿','Кольцо тайги','Восемь зверей признали тебя своим. Четыре амулета сложились в кольцо, и сама тайга приняла тебя как хранителя.']:['☠️','Путь оборвался','Холод и тьма оказались сильнее. В следующий раз подготовь лагерь и береги припасы.'];$('endingIcon').textContent=data[0];$('endingTitle').textContent=data[1];$('endingText').textContent=data[2]+` Прожито дней: ${player.days}.`; $('ending').classList.add('open');}
function startGame(){mode=document.querySelector('.mode-option.selected').dataset.mode;running=true;paused=false;gameTime=0;player={x:2.5,y:2.5,faceX:1,faceY:0,hp:100,food:82,water:76,warm:63,stamina:100,mind:92,dirt:4,bleed:0,poison:0,radiation:0,broken:false,days:1,season:0};for(let k in inventory)delete inventory[k];campBuilt=false;fire=null;enemy=null;animalsFound=0;amulets=0;radioParts=0;hasRadio=false;artifactActive=false;goal=0;caveFinds=0;buildMode=false;weatherIndex=0;weatherTimer=40;initNodes();give('wood',4);give('fiber',2);give('berries',2);give('water',1);give('stone',1);if(mode==='builder'){Object.keys(itemData).forEach(id=>inventory[id]=99);player.food=100;player.water=100;player.warm=85} $('startScreen').style.display='none';$('hud').style.display='block';$('ending').classList.remove('open');updateHUD();toast(mode==='builder'?'🪵 Режим архитектора · строй без ограничений':'🏕️ Найди место для первого привала. Ветки и волокно уже в рюкзаке.');last=performance.now();requestAnimationFrame(loop);}
function update(dt){if(!running||paused)return;gameTime+=dt;let dayTime=gameTime%60,day=Math.floor(gameTime/60)+1,night=dayTime>=40;let season=mode==='winter'?1:(Math.floor((day-1)/7)%4);let decay=dt;
player.food=Math.max(0,player.food-decay*.14);player.water=Math.max(0,player.water-decay*.2);let z=zoneAt(Math.floor(player.x),Math.floor(player.y));let cold=(night?1.5:.4)+(season===1?2.3:season===0?1:season===2?.5:0)+(weatherIndex===3?1.6:0)+(weatherIndex===1?.7:0)+(z.kind==='mountain'?1.5:0);player.warm=clamp(player.warm+(fire&&Math.hypot(player.x-2.5,player.y-2.5)<2?decay*1.1:-decay*cold*.13),0,100);player.mind=clamp(player.mind-(night&&!fire&&Math.random()<dt*.018?.09:0)+(fire&&night?dt*.01:0),0,100);player.dirt=clamp(player.dirt+decay*.006,0,100);if(player.food===0||player.water===0)player.hp-=decay*(player.water===0?1.2:.55);if(player.warm<15)player.hp-=decay*.45;if(player.bleed)player.hp-=decay*.7;if(player.poison){player.hp-=decay*.23;player.poison=Math.max(0,player.poison-decay*.1)}if(player.radiation>0){player.radiation=Math.max(0,player.radiation-decay*.012);player.hp-=decay*player.radiation*.0009}if(player.hp<=0){player.hp=0;if(mode==='hardcore')endingNow('death');else{player.hp=60;player.food=40;player.water=35;player.warm=50;player.x=2.5;player.y=2.5;player.bleed=0;player.broken=false;toast('🏕️ Ты очнулся в биваке. Запасы и силы потеряны.')}}
if(player.food<=0||player.water<=0||player.warm<8)player.hp-=0; if(fire){fire.fuel-=dt;if(fire.fuel<=0){fire=null;toast('🔥 Костёр погас — нужно больше веток')}}weatherTimer-=dt;if(weatherTimer<=0){weatherIndex=mode==='winter'? [0,2,3,3,5][Math.floor(Math.random()*5)]:Math.floor(Math.random()*weatherList.length);weatherTimer=35+Math.random()*45;if(weatherIndex===4&&campBuilt&&Math.random()<.14){campBuilt=false;fire=null;toast('⚡ Молния подожгла и разрушила лагерь!')}}for(let n of resourceNodes){if(!n.alive&&n.regrow>0){n.regrow-=dt/30;if(n.regrow<=0)n.alive=true}}
if(night&&!enemy&&Math.random()<dt*(weatherIndex===2?.013:.003)&&mode!=='builder'){let ex=player.x+(Math.random()<.5?-1:1)*(3+Math.random()*3),ey=player.y+(Math.random()<.5?-1:1)*(2+Math.random()*2);enemy={x:ex,y:ey,hp:60,max:60,icon:player.mind<25?'👹':'🐺',attack:0};toast('🐺 В темноте слышен вой…')}
if(enemy){let d=Math.hypot(enemy.x-player.x,enemy.y-player.y);if(d>1.3){enemy.x+=(player.x-enemy.x)/d*dt*.22;enemy.y+=(player.y-enemy.y)/d*dt*.22}else{enemy.attack-=dt;if(enemy.attack<=0){enemy.attack=3.5;player.hp-=8;player.bleed=12;player.mind=Math.max(0,player.mind-5);toast('🩸 Зверь атаковал! Отгони его копьём.')}}}
for(let i=debris.length-1;i>=0;i--){let d=debris[i];d.x+=d.vx*dt;d.y+=d.vy*dt;d.z=Math.max(0,d.z-dt*12);d.life-=dt;if(d.life<=0)debris.splice(i,1)}if(night&&player.days>=30&&mode!=='builder')endingNow('survive');updateHUD();}
let moving=false;function loop(now){if(!running)return;let dt=Math.min(.08,(now-last)/1000);last=now;if(!paused){update(dt);move(dt)}render();requestAnimationFrame(loop)}
function move(dt){let x=input.x+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),y=input.y+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);let mag=Math.hypot(x,y);if(mag>1){x/=mag;y/=mag}moving=mag>.08;if(moving){let speed=player.stamina>0?2.65:1.35;if(keys.ShiftLeft||keys.ShiftRight){if(player.stamina>0){speed*=1.5;player.stamina=Math.max(0,player.stamina-dt*12)}}else player.stamina=clamp(player.stamina+dt*6,0,100);let nx=clamp(player.x+x*dt*speed,0.2,24.8),ny=clamp(player.y+y*dt*speed,0.2,24.8);player.faceX=x;player.faceY=y;if(zoneAt(Math.floor(nx),Math.floor(ny)).kind==='lake'&&mode!=='winter'){player.water=clamp(player.water+dt*4,0,100);speed*=.55}player.x=nx;player.y=ny;let gx=Math.floor(player.x),gy=Math.floor(player.y);visited.add(gx+','+gy)}else player.stamina=clamp(player.stamina+dt*7,0,100)}
function setTool(t){selectedTool=t;['toolAxe','toolSpear','toolTorch'].forEach(id=>$(id).classList.remove('active'));let id=t==='axe'?'toolAxe':t==='spear'?'toolSpear':'toolTorch';$(id).classList.add('active')}

